/**
 * GENERATED by the recording pipeline for journey 'fixture_demo'.
 * Starter-vocabulary steps are real implementations over the component
 * objects; raw steps throw until a human names them (grammar growth).
 * Regenerate rather than hand-editing recognized steps.
 */
import type { StepCatalog } from '../catalog';

export function registerSteps_fixture_demo(catalog: StepCatalog): StepCatalog {
  return catalog
    .register('recordPage.open', async ({ page, args }) => {
      await page.goto('/lightning/r/' + String(args.sobject) + '/' + String(args.id) + '/view');
    })
    .register('form.fill', async ({ page, args }) => {
      await page.getByLabel(String(args.label)).fill(String(args.value));
    })
    .register('combobox.select', async ({ lightning, args }) => {
      await lightning.combobox(String(args.label)).select(String(args.option));
    })
    .register('modal.save', async ({ page, lightning, args }) => {
      const settled = args.settle === 'aura' ? lightning.auraResponse() : undefined;
      await page.getByRole('button', { name: String(args.button) }).click();
      if (settled) await settled;
    });
}
